window.HOGAN_EXTRAS["1144029706"] = window.HOGAN_EXTRAS["1144029706"] || {};
window.HOGAN_EXTRAS["1144029706"].fortalezas = "Su experiencia como supervisor de calle le ha permitido desarrollar una comprensi\u00f3n cercana de la operaci\u00f3n y una visi\u00f3n pr\u00e1ctica del negocio. Se caracteriza por su versatilidad, capacidad de adaptaci\u00f3n y disposici\u00f3n para asumir nuevos retos. Adem\u00e1s, cuenta con una comunicaci\u00f3n efectiva con sus pares, habilidad para cohesionar equipos, movilizar personas hacia objetivos comunes y generar resultados. Su liderazgo cercano, orientaci\u00f3n al logro, capacidad de influencia y motivaci\u00f3n por crecer le permiten impulsar iniciativas y fortalecer su impacto dentro de la organizaci\u00f3n.";
window.HOGAN_EXTRAS["1144029706"].oportunidades = "Fortalecer su comunicaci\u00f3n e influencia en niveles jer\u00e1rquicos superiores, desarrollando mayor seguridad y presencia ejecutiva. Incrementar la confianza para exponer sus ideas y defender su visi\u00f3n en escenarios de alta direcci\u00f3n le permitir\u00e1 ampliar su impacto, consolidar su posicionamiento y fortalecer su capacidad de influencia estrat\u00e9gica.";

window.HOGAN_EXTRAS["94527210"] = window.HOGAN_EXTRAS["94527210"] || {};
window.HOGAN_EXTRAS["94527210"].fortalezas = "Cuenta con una amplia experiencia en el canal, respaldada por un profundo conocimiento del negocio, especialmente en el segmento de prepago y el entorno comercial de calle. Su trayectoria de aproximadamente 10 a\u00f1os le ha permitido consolidar una s\u00f3lida comprensi\u00f3n de la operaci\u00f3n y generar cercan\u00eda con su equipo. Se caracteriza por su capacidad para coordinar la gesti\u00f3n, mantener una adecuada ejecuci\u00f3n de los presupuestos y obtener resultados consistentes gracias a su orden y conocimiento del negocio.";
window.HOGAN_EXTRAS["94527210"].oportunidades = "Fortalecer una visi\u00f3n m\u00e1s integral del negocio, desarrollando mayor capacidad anal\u00edtica y un enfoque basado en datos para la toma de decisiones. Asimismo, potenciar su liderazgo mediante una mayor influencia sobre el equipo y un enfoque m\u00e1s decidido en el desarrollo de las personas. Es importante incrementar su versatilidad, apertura al cambio y disposici\u00f3n para explorar nuevas formas de trabajo, ampliando su experiencia hacia otros canales o modelos de negocio. Adicionalmente, requiere fortalecer la disciplina en el seguimiento de iniciativas y mantener una motivaci\u00f3n sostenida frente a nuevos desaf\u00edos, favoreciendo un desarrollo m\u00e1s continuo y una mayor contribuci\u00f3n estrat\u00e9gica.";

window.HOGAN_EXTRAS["29284580"] = window.HOGAN_EXTRAS["29284580"] || {};
window.HOGAN_EXTRAS["29284580"].fortalezas = "Se destaca por su capacidad de proponer iniciativas, resolver problemas y mantener un desempe\u00f1o s\u00f3lido. Su trayectoria dentro de la compa\u00f1\u00eda, Su trayectoria refuerza su conocimiento del negocio y su evoluci\u00f3n como l\u00edder. Es una persona estructurada, con m\u00e9todo, buena capacidad de negociaci\u00f3n y alta reacci\u00f3n ante situaciones complejas. Es percibida como una de las gerentes m\u00e1s s\u00f3lidas y con mayor recorrido dentro del grupo.";
window.HOGAN_EXTRAS["29284580"].oportunidades = "Debe fortalecer su exposici\u00f3n en escenarios directivos y su capacidad de interlocuci\u00f3n con l\u00edderes transversales, especialmente a nivel de alta direcci\u00f3n. Requiere profundizar su conocimiento operativo y t\u00e9cnico del negocio, complementando su visi\u00f3n general con mayor entendimiento de conceptos m\u00e1s especializados.\nTambi\u00e9n es importante potenciar su curiosidad y cuestionamiento del negocio, ampliando su participaci\u00f3n en espacios de aprendizaje transversal, acompa\u00f1ada de iniciativas de desarrollo como \u201cpadrinos\u201d o exposici\u00f3n a otras \u00e1reas.\nEs clave asegurar su inter\u00e9s y motivaci\u00f3n por el crecimiento hacia roles de mayor responsabilidad, as\u00ed como ampliar su visi\u00f3n estrat\u00e9gica para consolidar su camino hacia la Direcci\u00f3n de Canales de Atenci\u00f3n.";

